package nl.smartstreamlabs.sbwdroneconfig;
import com.google.gson.*;import java.util.*;import net.minecraft.world.phys.*;import org.joml.Matrix4d;import org.joml.Vector3d;
/** Immutable original mesh metadata, including the exact supplied bay order and anchors. */
public final class Ndc01Geometry {
 public record Bone(String name,int parent,Vector3d pivot,Vector3d rotation,JsonObject tracks){}
 public static final Ndc01Geometry MODEL=new Ndc01Geometry();public final List<Bone>bones=new ArrayList<>();public final Vec3[]payload=new Vec3[18];public final AABB bounds;public final JsonObject animations;public final Vec3 bow,mast;
 private Ndc01Geometry(){try(var r=new java.io.InputStreamReader(Objects.requireNonNull(getClass().getResourceAsStream("/assets/sbwdroneconfig/ndc01/carrier.json")),java.nio.charset.StandardCharsets.UTF_8)){var j=JsonParser.parseReader(r).getAsJsonObject();for(var v:j.getAsJsonArray("bones")){var b=v.getAsJsonObject();bones.add(new Bone(b.get("name").getAsString(),b.get("parent").getAsInt(),vec(b.getAsJsonArray("pivot")),vec(b.getAsJsonArray("rotation")),b.getAsJsonObject("tracks")));}var b=j.getAsJsonArray("bounds");bounds=new AABB(b.get(0).getAsDouble(),b.get(1).getAsDouble(),b.get(2).getAsDouble(),b.get(3).getAsDouble(),b.get(4).getAsDouble(),b.get(5).getAsDouble());for(var v:j.getAsJsonObject("integration").getAsJsonArray("bays")){var o=v.getAsJsonObject();var p=vec(o.getAsJsonArray("payload_origin_blocks"));payload[o.get("slot").getAsInt()]=new Vec3(p.x,p.y,p.z);}animations=j.getAsJsonObject("animations");bow=anchor("Bow_Camera_Anchor");mast=anchor("Mast_Camera_Anchor");}catch(java.io.IOException ex){throw new ExceptionInInitializerError(ex);}}
 private Vec3 anchor(String name){var p=bones.stream().filter(b->b.name.equals(name)).findFirst().orElseThrow().pivot;return new Vec3(p.x,p.y,p.z);}
 private static Vector3d vec(JsonArray a){return new Vector3d(a.get(0).getAsDouble(),a.get(1).getAsDouble(),a.get(2).getAsDouble());}
 public static Matrix4d frame(Ndc01Entity e,float partial){return new Matrix4d(e.getVehicleTransform(partial)).rotateY(Math.PI);}
 public static Vec3 point(Matrix4d m,Vec3 p){var v=m.transformPosition(new Vector3d(p.x,p.y,p.z));return new Vec3(v.x,v.y,v.z);}
 public Matrix4d[]transforms(Ndc01Entity entity,float partial){var out=new Matrix4d[bones.size()];for(int i=0;i<out.length;i++){var b=bones.get(i);var r=new Vector3d(b.rotation);if(b.name.matches("Hatch_\\d\\d")&&entity.busy()&&Integer.parseInt(b.name.substring(6))-1==entity.bay()){int slot=Integer.parseInt(b.name.substring(6))-1;double time=entity.hatchTime(slot,partial);String clip=String.format(java.util.Locale.ROOT,"animation.mv11.hatch_%02d_%s",slot+1,entity.closing()?"close":"open");var a=animations.getAsJsonObject(clip).getAsJsonObject("animators");for(var anim:a.entrySet()){var keys=anim.getValue().getAsJsonObject().getAsJsonArray("keyframes");JsonObject prev=null;for(var value:keys){var k=value.getAsJsonObject();if(!k.get("channel").getAsString().equals("rotation"))continue;double at=k.get("time").getAsDouble();if(time<=at){var to=rotation(k);r.add(prev==null?to:rotation(prev).lerp(to,Math.max(0,Math.min(1,(time-prev.get("time").getAsDouble())/Math.max(.00001,at-prev.get("time").getAsDouble())))));prev=null;break;}prev=k;}if(prev!=null)r.add(rotation(prev));}}out[i]=new Matrix4d(b.parent<0?new Matrix4d():out[b.parent]).translate(b.pivot).rotateZYX(Math.toRadians(r.z),Math.toRadians(r.y),Math.toRadians(r.x)).translate(-b.pivot.x,-b.pivot.y,-b.pivot.z);}return out;}
 private static Vector3d rotation(JsonObject k){var v=k.getAsJsonArray("data_points").get(0).getAsJsonObject();return new Vector3d(v.get("x").getAsDouble(),v.get("y").getAsDouble(),v.get("z").getAsDouble());}
 private Ndc01Geometry(boolean unused){throw new AssertionError();}
}
